'use strict';
const $ = id => document.getElementById(id);
const levels = [{code:'R3',price:2813,name:'Resistance 3'},{code:'R2',price:2683,name:'Resistance 2'},{code:'R1',price:2554,name:'Immediate resistance'},{code:'S1',price:2416,name:'Immediate support'},{code:'S2',price:2373,name:'Support 2'},{code:'S3',price:2320,name:'Support 3'}];
const state = {price:null,candles:[],days:90,armed:true,zone:null,events:[],lastSuccess:0,lastCandles:0,busy:false,chartData:[],stats:null};
const usd = n => Number.isFinite(n) ? n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}) : '—';
const short = n => Number.isFinite(n) ? '$'+Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n) : '—';
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try {state.events=JSON.parse(localStorage.getItem('etherwatch-alerts')||'[]').filter(e=>e&&typeof e.message==='string'&&Number.isFinite(e.time)).slice(0,50);state.armed=localStorage.getItem('etherwatch-armed')!=='false';} catch {}
function persist(){try{localStorage.setItem('etherwatch-alerts',JSON.stringify(state.events));localStorage.setItem('etherwatch-armed',String(state.armed));}catch{}}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',7000);}
function renderEvents(){ $('alert-count').textContent=state.events.length; if(!state.events.length)return; $('alert-list').innerHTML=state.events.map(e=>`<div class="event">${escapeHTML(e.message)}<small>${escapeHTML(new Date(e.time).toLocaleString())}</small></div>`).join(''); }
function checkAlert(price){const zone=price<2416?'below':price>2554?'above':'inside';if(state.armed&&zone!=='inside'&&zone!==state.zone){const message=`${state.zone===null?'Monitor started: ':''}ETH ${zone==='below'?'below $2,416 support':'above $2,554 resistance'} · ${usd(price)}`;state.events.unshift({message,time:Date.now()});state.events=state.events.slice(0,50);persist();renderEvents();toast(message);if('Notification' in window&&Notification.permission==='granted'){try{new Notification('Ether Watch · Price alert',{body:message,tag:'etherwatch-'+zone});}catch{}}}state.zone=zone;}
function renderLevels(){ $('level-list').innerHTML=levels.map(l=>`<div class="level ${l.code[0]==='S'?'support':''}"><span class="level-code">${l.code}</span><div><span class="level-name">${l.name}</span><span class="level-price">${usd(l.price)}</span></div><span class="level-distance">${state.price?((l.price/state.price-1)*100>=0?'+':'')+((l.price/state.price-1)*100).toFixed(2)+'%':'—'}</span></div>`).join(''); }
function ema(values,period){const out=Array(values.length).fill(null);if(values.length<period)return out;let v=values.slice(0,period).reduce((a,b)=>a+b,0)/period;out[period-1]=v;for(let i=period;i<values.length;i++){v=values[i]*2/(period+1)+v*(1-2/(period+1));out[i]=v;}return out;}
function rsi(values,period=14){if(values.length<=period)return null;let gain=0,loss=0;for(let i=1;i<=period;i++){const d=values[i]-values[i-1];gain+=Math.max(d,0)/period;loss+=Math.max(-d,0)/period;}for(let i=period+1;i<values.length;i++){const d=values[i]-values[i-1];gain=(gain*(period-1)+Math.max(d,0))/period;loss=(loss*(period-1)+Math.max(-d,0))/period;}return loss===0?(gain===0?50:100):100-100/(1+gain/loss);}
function completed(){return state.candles.filter(c=>c.time+86400<=Date.now()/1000);}
function indicators(){const candles=completed(),closes=candles.map(c=>c.close),strength=rsi(closes);if(strength!==null){$('momentum').textContent=strength.toFixed(1)+' '+(strength>=70?'Overbought':strength<=30?'Oversold':strength>=50?'Bullish':'Bearish');$('momentum').style.fontSize='23px';$('momentum').className='value '+(strength>=50?'positive':'negative');$('rsi-bar').style.width=strength+'%';}const fast=ema(closes,12),slow=ema(closes,26),macd=closes.map((_,i)=>fast[i]!==null&&slow[i]!==null?fast[i]-slow[i]:null).filter(x=>x!==null),signal=ema(macd,9);if(signal.length&&signal.at(-1)!==null){const h=macd.at(-1)-signal.at(-1);$('macd').textContent=(h>=0?'+':'')+h.toFixed(2)+' histogram';$('macd').className=h>=0?'positive':'negative';$('macd').title=`MACD ${macd.at(-1).toFixed(2)} / Signal ${signal.at(-1).toFixed(2)}`;}if(candles.length>20){const avg=candles.slice(-21,-1).reduce((sum,c)=>sum+c.volume,0)/20;$('rvol').textContent=avg>0?(candles.at(-1).volume/avg).toFixed(2)+'× average':'—';}if(closes.length){const series=closes.slice(-30),min=Math.min(...series),max=Math.max(...series);$('spark').setAttribute('d',series.map((v,i)=>`${i?'L':'M'}${i/(series.length-1)*180},${40-(v-min)/(max-min||1)*35}`).join(' '));}}
async function request(path){const response=await fetch('https://api.exchange.coinbase.com/products/ETH-USD/'+path,{signal:AbortSignal.timeout(12000),cache:'no-store'});if(!response.ok)throw new Error('Market feed returned '+response.status);return response.json();}
function updatePrice(ticker,stats){const price=Number(ticker.price),time=Date.parse(ticker.time);if(!Number.isFinite(price)||price<=0||!Number.isFinite(time)||Date.now()-time>120000)throw new Error('Price feed is stale or invalid');state.price=price;state.lastSuccess=Date.now();$('price').textContent=usd(price);$('connection').textContent='● Live · 15s updates';$('connection').style.color='var(--green)';$('updated').textContent='Updated '+new Date(time).toLocaleTimeString()+' · Coinbase';if(stats){const open=Number(stats.open),volume=Number(stats.volume);if(open>0){const change=(price/open-1)*100;$('change').textContent=(change>=0?'↗ +':'↘ ')+change.toFixed(2)+'%';$('change').className=change>=0?'positive':'negative';}if(Number.isFinite(volume))$('volume').textContent=short(volume*price);}$('range-pin').style.left=Math.max(0,Math.min(100,(price-2416)/138*100))+'%';$('range-note').textContent=price<2416?'Below immediate support':price>2554?'Above immediate resistance':'Within immediate range';$('structure').innerHTML=`<span class="eyebrow">${price<2416?'SUPPORT BREACH':price>2554?'RESISTANCE BREACH':'INSIDE THE WATCH ZONE'}</span><h3>${price<2416?'Watching $2,373':price>2554?'Watching $2,683':'Between key levels'}</h3><p>ETH is ${Math.abs(price/2416*100-100).toFixed(2)}% ${price>=2416?'above':'below'} S1 and ${Math.abs(price/2554*100-100).toFixed(2)}% ${price>=2554?'above':'below'} R1. Levels are your fixed reference points, not dynamically calculated predictions.</p>`;renderLevels();checkAlert(price);draw();}
async function refresh(){if(state.busy)return;state.busy=true;$('refresh').disabled=true;const needCandles=Date.now()-state.lastCandles>300000;const results=await Promise.allSettled([request('ticker'),request('stats'),...(needCandles?[request('candles?granularity=86400')]:[])]);if(results[1].status==='fulfilled')state.stats=results[1].value;if(results[0].status==='fulfilled'){try{updatePrice(results[0].value,state.stats);}catch(e){feedError(e.message);}}else feedError(results[0].reason.message);if(needCandles){if(results[2].status==='fulfilled'){const rows=results[2].value;if(Array.isArray(rows)){state.candles=rows.filter(r=>Array.isArray(r)&&r.length>=6&&r.every(Number.isFinite)&&r[1]>0&&r[2]>=r[1]&&r[5]>=0).map(r=>({time:r[0],low:r[1],high:r[2],open:r[3],close:r[4],volume:r[5]})).sort((a,b)=>a.time-b.time);if(state.candles.length){state.lastCandles=Date.now();$('chart-empty').style.display='none';indicators();draw();}else chartError();}else chartError();}else chartError();}state.busy=false;$('refresh').disabled=false;}
function feedError(message){$('connection').textContent=state.lastSuccess?'● Stale · reconnecting':'● Feed unavailable';$('connection').style.color='var(--red)';$('connection').title=message;$('updated').textContent=state.lastSuccess?'Last successful update '+new Date(state.lastSuccess).toLocaleTimeString():'Unable to reach Coinbase · retrying every 15s';}
function chartError(){if(!state.candles.length){$('chart-empty').style.display='flex';$('chart-empty').innerHTML='Daily chart unavailable<small>The data feed may be blocked or temporarily unavailable.</small>';}else{$('updated').textContent+=' · Daily candles stale';}}
function volumeProfile(candles,bins=30){if(!candles.length)return null;const min=Math.min(...candles.map(c=>c.low)),max=Math.max(...candles.map(c=>c.high)),step=(max-min||1)/bins,volumes=Array(bins).fill(0);for(const c of candles){if(c.high===c.low){volumes[Math.min(bins-1,Math.floor((c.close-min)/step))]+=c.volume;continue;}for(let i=0;i<bins;i++){const overlap=Math.max(0,Math.min(c.high,min+(i+1)*step)-Math.max(c.low,min+i*step));volumes[i]+=c.volume*overlap/(c.high-c.low);}}const peak=Math.max(...volumes);return {min,step,volumes,peak,poc:min+(volumes.indexOf(peak)+.5)*step};}
function draw(){const canvas=$('chart'),rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const data=state.candles.slice(-state.days);state.chartData=data;if(!data.length)return;const left=9,right=w-70,top=20,bottom=h-76,volumeBottom=h-28;const min=Math.min(...data.map(c=>c.low),2320,state.price||Infinity)*.985,max=Math.max(...data.map(c=>c.high),2813,state.price||0)*1.015;const y=p=>top+(max-p)/(max-min)*(bottom-top),step=(right-left)/data.length,x=i=>left+(i+.5)*step;state.geometry={left,right,step};ctx.font='10px DM Sans, sans-serif';ctx.textAlign='left';for(let i=0;i<5;i++){const p=min+(max-min)*i/4,py=y(p);ctx.strokeStyle='#292f32';ctx.beginPath();ctx.moveTo(left,py);ctx.lineTo(right,py);ctx.stroke();ctx.fillStyle='#798589';ctx.fillText(p.toLocaleString('en-US',{maximumFractionDigits:0}),right+10,py+4);}const profile=volumeProfile(data);if(profile&&profile.peak){$('poc').textContent=usd(profile.poc);if($('show-profile').checked){profile.volumes.forEach((v,i)=>{ctx.fillStyle=i===profile.volumes.indexOf(profile.peak)?'#c2ef8359':'#a1aba51c';ctx.fillRect(right-v/profile.peak*(right-left)*.24,y(profile.min+(i+1)*profile.step),v/profile.peak*(right-left)*.24,Math.max(1,y(profile.min+i*profile.step)-y(profile.min+(i+1)*profile.step)-1));});}}for(const l of levels){ctx.strokeStyle=l.code[0]==='S'?'#a9cb6566':'#e78e8766';ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(left,y(l.price));ctx.lineTo(right,y(l.price));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=l.code[0]==='S'?'#b5d58d':'#d59b96';ctx.font='9px DM Sans, sans-serif';ctx.fillText(l.code+' '+l.price,right+5,y(l.price)-4);}const maxVolume=Math.max(...data.map(c=>c.volume))||1;data.forEach((c,i)=>{const color=c.close>=c.open?'#bce58a':'#d88780';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x(i),y(c.high));ctx.lineTo(x(i),y(c.low));ctx.stroke();ctx.fillRect(x(i)-Math.max(1,step*.57)/2,y(Math.max(c.open,c.close)),Math.max(1,step*.57),Math.max(1,Math.abs(y(c.open)-y(c.close))));ctx.globalAlpha=.3;ctx.fillRect(x(i)-step*.3,volumeBottom-c.volume/maxVolume*38,step*.6,c.volume/maxVolume*38);ctx.globalAlpha=1;if(i>0&&c.time+86400<=Date.now()/1000){for(const l of levels){if((data[i-1].close<l.price&&c.close>=l.price)||(data[i-1].close>l.price&&c.close<=l.price)){ctx.fillStyle='#b6abec';ctx.beginPath();ctx.arc(x(i),y(l.price),2.6,0,Math.PI*2);ctx.fill();}}}if(i%Math.max(1,Math.floor(data.length/5))===0){ctx.fillStyle='#798589';ctx.font='9px DM Sans, sans-serif';ctx.fillText(new Date(c.time*1000).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),x(i),h-7);}});if(state.price){ctx.setLineDash([2,3]);ctx.strokeStyle='#edf0ed66';ctx.beginPath();ctx.moveTo(left,y(state.price));ctx.lineTo(right,y(state.price));ctx.stroke();ctx.setLineDash([]);}}
$('chart').addEventListener('pointermove',event=>{if(!state.geometry)return;const rect=$('chart').getBoundingClientRect(),i=Math.floor((event.clientX-rect.left-state.geometry.left)/state.geometry.step),c=state.chartData[i];if(!c){$('tooltip').hidden=true;return;}$('tooltip').hidden=false;$('tooltip').innerHTML=`${new Date(c.time*1000).toISOString().slice(0,10)} UTC${c.time+86400>Date.now()/1000?' · In progress':''}<br>O ${usd(c.open)} · H ${usd(c.high)}<br>L ${usd(c.low)} · C ${usd(c.close)}<br>Volume ${c.volume.toLocaleString('en-US',{maximumFractionDigits:0})} ETH`;});
$('chart').addEventListener('pointerleave',()=>{$('tooltip').hidden=true;});
document.querySelectorAll('[data-days]').forEach(button=>button.addEventListener('click',()=>{state.days=Number(button.dataset.days);document.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('selected',b===button));draw();}));
$('show-profile').addEventListener('change',draw);$('refresh').addEventListener('click',refresh);
function renderArmed(){$('pause').textContent=state.armed?'Pause alerts':'Resume alerts';$('armed-badge').textContent=state.armed?'ARMED':'PAUSED';document.querySelector('.alert-settings p').textContent=`Below $2,416 or above $2,554. In-page alerts are ${state.armed?'active':'paused'}.`;}
$('pause').addEventListener('click',()=>{state.armed=!state.armed;state.zone=null;persist();renderArmed();if(state.armed&&state.price&&Date.now()-state.lastSuccess<30000)checkAlert(state.price);});
$('notify').addEventListener('click',async()=>{if(!('Notification' in window)){toast('This browser does not support desktop notifications. In-page alerts remain available.');return;}try{const permission=await Notification.requestPermission();$('notification-note').textContent=permission==='granted'?'Browser notifications enabled. Keep this page open and connected.':'Notifications are not enabled. You can change permission in browser settings; in-page alerts still work.';$('notify').textContent=permission==='granted'?'Notifications enabled':'Enable notifications';}catch{toast('Browser notifications unavailable. In-page alerts remain active.');}});
new ResizeObserver(draw).observe($('chart'));renderLevels();renderEvents();renderArmed();refresh();setInterval(refresh,15000);setInterval(()=>{if(state.lastSuccess&&Date.now()-state.lastSuccess>45000)feedError('No recent successful update');},5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
